(7288691, 1135842, 175719, '<td valign="top">This image is absolutely amazing.  You did a great job - you took a hard boring challenge entered into a work of art!</td>', 'This image is absolutely amazing.  You did a great job - you took a hard boring challenge entered into a work of art!', '2014-11-30 23:11:17.000000', NULL, 1),
(7288692, 1136023, 175719, '<td valign="top">That is a great picture of a cat I really wish this was a cat challenge if it was I would give you a 10.  Sad to say it''s a chair challenge and I don''t think the chair says much in this photo,  it''s been way upstaged by the cat.  It''s still a great picture and I have to give you a fairly good score for that.</td>', 'That is a great picture of a cat I really wish this was a cat challenge if it was I would give you a 10.  Sad to say it''s a chair challenge and I don''t think the chair says much in this photo,  it''s been way upstaged by the cat.  It''s still a great picture and I have to give you a fairly good score for that.', '2014-11-30 23:13:47.000000', NULL, 1),
(7288693, 1136058, 175719, '<td valign="top">Amazing photo- I don''t know if it says chair but I love that kid.</td>', 'Amazing photo- I don''t know if it says chair but I love that kid.', '2014-11-30 23:16:52.000000', NULL, 1),
(7288884, 1136058, 96574, '<td valign="top">First thing that comes to mind...Dark Rockwell...lol.  <br/>Very well done and my pick for the blue</td>', 'First thing that comes to mind...Dark Rockwell...lol.  Very well done and my pick for the blue', '2014-12-01 15:44:30.000000', NULL, 1),
