(7289295, 1136001, 13077, '<td valign="top">Very fancy indeed. I like the old flooring it''s on too.</td>', 'Very fancy indeed. I like the old flooring it''s on too.', '2014-12-02 20:26:12.000000', NULL, 1),
(7289297, 1135984, 13077, '<td valign="top">I wonder how comfy the chair is, but it''s an attractive scene and the processing matches it.</td>', 'I wonder how comfy the chair is, but it''s an attractive scene and the processing matches it.', '2014-12-02 20:26:55.000000', NULL, 1),
(7289300, 1136058, 13077, '<td valign="top">Perfect - so true! My top pick so far.</td>', 'Perfect - so true! My top pick so far.', '2014-12-02 20:27:37.000000', NULL, 1),
(7289301, 1136046, 13077, '<td valign="top">Funky-licious.</td>', 'Funky-licious.', '2014-12-02 20:28:00.000000', NULL, 1),
(7289303, 1136014, 13077, '<td valign="top">I like the minimalist approach to this one. Great angle of light and shadow position.</td>', 'I like the minimalist approach to this one. Great angle of light and shadow position.', '2014-12-02 20:28:23.000000', NULL, 1),
(7289305, 1136056, 13077, '<td valign="top">I like the juxtaposition of the indoor chair to the forest. Did you find it out there?<br/>I''ve gotta say though, the big stain on the chair back is distracting.</td>', 'I like the juxtaposition of the indoor chair to the forest. Did you find it out there?I''ve gotta say though, the big stain on the chair back is distracting.', '2014-12-02 20:29:24.000000', NULL, 1),
(7289307, 1135980, 13077, '<td valign="top">Good angle of view and fairly clean composition, but the white balance seems a bit off and the blown-out sky is distracting in my opinion.</td>', 'Good angle of view and fairly clean composition, but the white balance seems a bit off and the blown-out sky is distracting in my opinion.', '2014-12-02 20:30:15.000000', NULL, 1),
(7289308, 1136025, 13077, '<td valign="top">LOL - seems like a real life cartoon scene.</td>', 'LOL - seems like a real life cartoon scene.', '2014-12-02 20:30:41.000000', NULL, 1),
(7289309, 1135959, 13077, '<td valign="top">I would have liked it more without the rug in the background.</td>', 'I would have liked it more without the rug in the background.', '2014-12-02 20:31:00.000000', NULL, 1),
(7289312, 1135960, 13077, '<td valign="top">Excellent light and composition. Very interesting find, and perfect for the challenge.</td>', 'Excellent light and composition. Very interesting find, and perfect for the challenge.', '2014-12-02 20:31:33.000000', NULL, 1),
(7289313, 1136082, 13077, '<td valign="top">Nice - simple, and just enough detail in the water in the background there.</td>', 'Nice - simple, and just enough detail in the water in the background there.', '2014-12-02 20:31:50.000000', NULL, 1),
(7289317, 1136029, 13077, '<td valign="top">The light beam and shadow on the wall there is a nice touch. There might have been a few other compositions that would have worked well (maybe a little better, hard to say) for this scene, but this one is pretty good.</td>', 'The light beam and shadow on the wall there is a nice touch. There might have been a few other compositions that would have worked well (maybe a little better, hard to say) for this scene, but this one is pretty good.', '2014-12-02 20:33:04.000000', NULL, 1),
(7289318, 1135918, 13077, '<td valign="top">Cute. Having poor Geoffrey''s name cut off by the dunce cap while the other wall has a lot of blank space kind of bugs me though.</td>', 'Cute. Having poor Geoffrey''s name cut off by the dunce cap while the other wall has a lot of blank space kind of bugs me though.', '2014-12-02 20:33:46.000000', NULL, 1),
(7289320, 1136052, 13077, '<td valign="top">Very cool. The name gives it some creepiness.</td>', 'Very cool. The name gives it some creepiness.', '2014-12-02 20:34:17.000000', NULL, 1),
(7289321, 1136090, 13077, '<td valign="top">Great contrasty light, the shadow is awesome and the tones look great. Good detail on the ground (is it a roof?) too.</td>', 'Great contrasty light, the shadow is awesome and the tones look great. Good detail on the ground (is it a roof?) too.', '2014-12-02 20:35:01.000000', NULL, 1),
(7289322, 1135842, 13077, '<td valign="top">Oh wow, that''s dedication. Nicely done.</td>', 'Oh wow, that''s dedication. Nicely done.', '2014-12-02 20:35:14.000000', NULL, 1),
(7289324, 1135899, 13077, '<td valign="top">Visually strong. I suppose that''s the arm of a chair so at least it sort of meets the challenge.</td>', 'Visually strong. I suppose that''s the arm of a chair so at least it sort of meets the challenge.', '2014-12-02 20:35:50.000000', NULL, 1),
(7289325, 1135833, 13077, '<td valign="top">Good, clean composition and nice light and tones.</td>', 'Good, clean composition and nice light and tones.', '2014-12-02 20:36:11.000000', NULL, 1),
(7289327, 1135747, 13077, '<td valign="top">Very nice scene. Has a lonely vibe to it.</td>', 'Very nice scene. Has a lonely vibe to it.', '2014-12-02 20:36:27.000000', NULL, 1),
(7289329, 1135979, 13077, '<td valign="top">Interesting place for sure. Nice light, and the dark top half of the photo adds some uneasiness to the overall feel. I like I would have cropped out the far left where the wall is a different color, though.</td>', 'Interesting place for sure. Nice light, and the dark top half of the photo adds some uneasiness to the overall feel. I like I would have cropped out the far left where the wall is a different color, though.', '2014-12-02 20:37:28.000000', NULL, 1),
(7289330, 1136066, 13077, '<td valign="top">Strong composition, clean. The slight blur works well.</td>', 'Strong composition, clean. The slight blur works well.', '2014-12-02 20:37:48.000000', NULL, 1),
(7289331, 1136068, 13077, '<td valign="top">Something visually pleasing about this. Good variety of colors/textures here, and well laid-out.</td>', 'Something visually pleasing about this. Good variety of colors/textures here, and well laid-out.', '2014-12-02 20:38:22.000000', NULL, 1),
(7289332, 1135991, 13077, '<td valign="top">Pinhole? <br/>The emptiness of the foreground is a bold move - combined with the title it at least draws our interest in to wonder what should be there and why it isn''t.</td>', 'Pinhole? The emptiness of the foreground is a bold move - combined with the title it at least draws our interest in to wonder what should be there and why it isn''t.', '2014-12-02 20:39:43.000000', NULL, 1),
(7289333, 1135973, 13077, '<td valign="top">Well composed. If the grain was added, I think it might be stronger without it, because it''s the major visual elements that give this its appeal; grittiness doesn''t seem to fit it in my opinion.</td>', 'Well composed. If the grain was added, I think it might be stronger without it, because it''s the major visual elements that give this its appeal; grittiness doesn''t seem to fit it in my opinion.', '2014-12-02 20:40:53.000000', NULL, 1),
(7289334, 1135972, 13077, '<td valign="top">Was the work removing the ties?</td>', 'Was the work removing the ties?', '2014-12-02 20:41:17.000000', NULL, 1),
(7289335, 1135990, 13077, '<td valign="top">Hopefully it''s a rehearsal, lol</td>', 'Hopefully it''s a rehearsal, lol', '2014-12-02 20:41:50.000000', NULL, 1),
(7289337, 1136051, 13077, '<td valign="top">Is that a land cruiser prado?<br/> <br/>The scene looks nice, but I would have recommended a darker curves layer with a gradiated mask to darken approximately the top half of the scene a bit - the detail is there, it would just be easier on the eyes as a photo that way.</td>', 'Is that a land cruiser prado? The scene looks nice, but I would have recommended a darker curves layer with a gradiated mask to darken approximately the top half of the scene a bit - the detail is there, it would just be easier on the eyes as a photo that way.', '2014-12-02 20:43:18.000000', NULL, 1),
(7289338, 1135794, 13077, '<td valign="top">Looks like an enjoyable, nice place to relax.Well composed; can be tough with a fisheye.</td>', 'Looks like an enjoyable, nice place to relax.Well composed; can be tough with a fisheye.', '2014-12-02 20:43:50.000000', NULL, 1),
(7289341, 1136080, 13077, '<td valign="top">I like it - the light falloff and the grittiness are interesting, and it''s well composed.</td>', 'I like it - the light falloff and the grittiness are interesting, and it''s well composed.', '2014-12-02 20:44:29.000000', NULL, 1),
(7289342, 1136013, 13077, '<td valign="top">I''m not crazy about it - the dog''s pose is nice, but I think a more interesting and cleaner composition could have been found.</td>', 'I''m not crazy about it - the dog''s pose is nice, but I think a more interesting and cleaner composition could have been found.', '2014-12-02 20:44:53.000000', NULL, 1),
(7289343, 1136023, 13077, '<td valign="top">LOL - soon enough, kitty... soon enough. <br/>Nicely done. I like the white cat in the low-key subdued-tone scene.</td>', 'LOL - soon enough, kitty... soon enough. Nicely done. I like the white cat in the low-key subdued-tone scene.', '2014-12-02 20:45:30.000000', NULL, 1),
(7289344, 1135859, 13077, '<td valign="top">Nice. The hanging hat is a great touch and the grittiness fits it well.</td>', 'Nice. The hanging hat is a great touch and the grittiness fits it well.', '2014-12-02 20:46:02.000000', NULL, 1),
(7289345, 1136094, 13077, '<td valign="top">What the heck? lol<br/>Very striking and interesting.</td>', 'What the heck? lolVery striking and interesting.', '2014-12-02 20:46:36.000000', NULL, 1),
(7289346, 1136086, 13077, '<td valign="top">I like it. Good textures and light, and I like the straight-on, centered composition here.</td>', 'I like it. Good textures and light, and I like the straight-on, centered composition here.', '2014-12-02 20:47:08.000000', NULL, 1),
(7289348, 1135968, 13077, '<td valign="top">Those are very cool benches. Not crazy about the sort of greenish tint overall though.</td>', 'Those are very cool benches. Not crazy about the sort of greenish tint overall though.', '2014-12-02 20:47:40.000000', NULL, 1),
(7289349, 1136011, 13077, '<td valign="top">Nice. The light, shapes and tones all go together well and compliment that mural. Well composed too.</td>', 'Nice. The light, shapes and tones all go together well and compliment that mural. Well composed too.', '2014-12-02 20:48:09.000000', NULL, 1),
(7289352, 1135969, 13077, '<td valign="top">Excellent exposure (HDR I''m guessing) and a very good journalistic-type photo.</td>', 'Excellent exposure (HDR I''m guessing) and a very good journalistic-type photo.', '2014-12-02 20:49:36.000000', NULL, 1),
(7289354, 1136085, 13077, '<td valign="top">It''s a very classic looking scene, but there''s a bit of motion blur or some kind of softness.</td>', 'It''s a very classic looking scene, but there''s a bit of motion blur or some kind of softness.', '2014-12-02 20:50:24.000000', NULL, 1),
(7289355, 1135744, 13077, '<td valign="top">Nice arrangement - the texture goes well with the chair and case.</td>', 'Nice arrangement - the texture goes well with the chair and case.', '2014-12-02 20:50:45.000000', NULL, 1),
(7289356, 1135987, 13077, '<td valign="top">I think the chair really gets lost in the busy background here.</td>', 'I think the chair really gets lost in the busy background here.', '2014-12-02 20:51:00.000000', NULL, 1),
(7289357, 1136040, 13077, '<td valign="top">Certainly colorful. And it certainly meets the challenge. Overall, I''m not crazy about it - something about the crop or the processing looks like it has room for improvement. Maybe a slightly looser crop, and some reined-in highlights would have gone a long way.</td>', 'Certainly colorful. And it certainly meets the challenge. Overall, I''m not crazy about it - something about the crop or the processing looks like it has room for improvement. Maybe a slightly looser crop, and some reined-in highlights would have gone a long way.', '2014-12-02 20:52:19.000000', NULL, 1),
(7289358, 1135757, 13077, '<td valign="top">Cool - good light, nicely composed and the sort of soft focus effect suits it well.</td>', 'Cool - good light, nicely composed and the sort of soft focus effect suits it well.', '2014-12-02 20:52:45.000000', NULL, 1),
(7289359, 1135905, 13077, '<td valign="top">Very nice perspective and symmetry. Not super crazy about the very bright left side and the much darker right side, but it might have been tough to add a fill light and get it all color balanced. I prefer the darker look of the right side, though.</td>', 'Very nice perspective and symmetry. Not super crazy about the very bright left side and the much darker right side, but it might have been tough to add a fill light and get it all color balanced. I prefer the darker look of the right side, though.', '2014-12-02 20:54:03.000000', NULL, 1),
(7289360, 1135787, 13077, '<td valign="top">It''s a Chair!</td>', 'It''s a Chair!', '2014-12-02 20:54:14.000000', NULL, 1),
(7289361, 1135779, 13077, '<td valign="top">LOL - yep, doggie knows his/her rights.</td>', 'LOL - yep, doggie knows his/her rights.', '2014-12-02 20:54:29.000000', NULL, 1),
(7289362, 1135810, 13077, '<td valign="top">Fascinating wall there.</td>', 'Fascinating wall there.', '2014-12-02 20:54:40.000000', NULL, 1),
(7289364, 1135993, 13077, '<td valign="top">Nicely done. Good light and composition, and very nice scene with the two straight rows of trees for a backdrop.</td>', 'Nicely done. Good light and composition, and very nice scene with the two straight rows of trees for a backdrop.', '2014-12-02 20:55:12.000000', NULL, 1),
(7289365, 1135908, 13077, '<td valign="top">The cracking/peeling paint and the leaves on the ground are perfect for this. I like it a lot.</td>', 'The cracking/peeling paint and the leaves on the ground are perfect for this. I like it a lot.', '2014-12-02 20:55:37.000000', NULL, 1),
(7289366, 1136057, 13077, '<td valign="top">A tiny chair? Why would I need that, when I have human laps and pillows to lie on???</td>', 'A tiny chair? Why would I need that, when I have human laps and pillows to lie on???', '2014-12-02 20:56:03.000000', NULL, 1),
(7289367, 1136030, 13077, '<td valign="top">BOGEYS INCOMING AT 2 O''CLOCK!!!<br/>oh, never mind, the glass window took care of them.</td>', 'BOGEYS INCOMING AT 2 O''CLOCK!!!oh, never mind, the glass window took care of them.', '2014-12-02 20:56:32.000000', NULL, 1),
(7289371, 1136051, 68504, '<td valign="top">beautiful and banal duking it out. a courageous entry.</td>', 'beautiful and banal duking it out. a courageous entry.', '2014-12-02 20:58:54.000000', NULL, 1),
(7289372, 1136090, 68504, '<td valign="top">you''re giving us the late afternoon glitters. great lines.</td>', 'you''re giving us the late afternoon glitters. great lines.', '2014-12-02 21:00:08.000000', NULL, 1),
(7289374, 1135969, 68504, '<td valign="top">this occasions the use of the word "plangent." if it doesn''t mean the effect of this picture, it ought to.</td>', 'this occasions the use of the word "plangent." if it doesn''t mean the effect of this picture, it ought to.', '2014-12-02 21:02:44.000000', NULL, 1),
